<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/vendor.php';
send_cors_headers();$context=require_vendor(true);$vendorId=$context['vendor']['id'];$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->prepare('SELECT p.id AS product_id,p.name,p.status,v.id AS variant_id,v.name AS variant_name,v.sku,i.stock_quantity,i.reserved_quantity,(i.stock_quantity-i.reserved_quantity) AS available_quantity,i.low_stock_threshold FROM products p JOIN product_variants v ON v.product_id=p.id JOIN inventory_levels i ON i.variant_id=v.id WHERE p.vendor_id=:vendor ORDER BY p.name,v.name');$stmt->execute(['vendor'=>$vendorId]);$inventory=$stmt->fetchAll();$history=$db->prepare('SELECT m.id,m.variant_id,m.movement_type,m.quantity_delta,m.reserved_delta,m.stock_after,m.reserved_after,m.note,m.created_at,v.sku,p.name AS product_name FROM inventory_movements m JOIN product_variants v ON v.id=m.variant_id JOIN products p ON p.id=v.product_id WHERE m.vendor_id=:vendor ORDER BY m.created_at DESC,m.id DESC LIMIT 100');$history->execute(['vendor'=>$vendorId]);json_response(200,['success'=>true,'inventory'=>$inventory,'movements'=>$history->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$variantId=trim((string)($body['variant_id']??''));$delta=filter_var($body['quantity_delta']??null,FILTER_VALIDATE_INT);$note=trim((string)($body['note']??''));if($delta===false||$delta===0||abs($delta)>100000||mb_strlen($note)<3)json_response(422,['success'=>false,'message'=>'Enter a valid non-zero stock adjustment and reason.']);$db->beginTransaction();try{$stmt=$db->prepare('SELECT i.*,p.id AS product_id FROM inventory_levels i JOIN product_variants v ON v.id=i.variant_id JOIN products p ON p.id=v.product_id WHERE i.variant_id=:variant AND p.vendor_id=:vendor FOR UPDATE');$stmt->execute(['variant'=>$variantId,'vendor'=>$vendorId]);$level=$stmt->fetch();if(!$level)json_response(404,['success'=>false,'message'=>'Inventory item not found.']);$after=(int)$level['stock_quantity']+$delta;if($after<(int)$level['reserved_quantity']||$after<0)json_response(409,['success'=>false,'message'=>'Stock cannot fall below reserved quantity or zero.']);$db->prepare('UPDATE inventory_levels SET stock_quantity=:stock,updated_at=UTC_TIMESTAMP() WHERE variant_id=:variant')->execute(['stock'=>$after,'variant'=>$variantId]);$db->prepare('INSERT INTO inventory_movements (variant_id,vendor_id,movement_type,quantity_delta,reserved_delta,stock_after,reserved_after,note,actor_type,actor_id,created_at) VALUES (:variant,:vendor,"manual_adjustment",:delta,0,:stock,:reserved,:note,"vendor",:actor,UTC_TIMESTAMP())')->execute(['variant'=>$variantId,'vendor'=>$vendorId,'delta'=>$delta,'stock'=>$after,'reserved'=>(int)$level['reserved_quantity'],'note'=>$note,'actor'=>$vendorId]);audit_event('vendor.inventory_adjusted','product',$level['product_id'],['variant_id'=>$variantId,'quantity_delta'=>$delta,'stock_after'=>$after]);$db->commit();json_response(200,['success'=>true,'message'=>'Inventory adjusted.','stock_quantity'=>$after,'reserved_quantity'=>(int)$level['reserved_quantity'],'available_quantity'=>$after-(int)$level['reserved_quantity']]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
json_response(405,['success'=>false,'message'=>'Method not allowed.']);
